input.command:
cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
CREATE TABLE IF NOT EXISTS list_raw AS
SELECT row_number() OVER () AS rn, cod_imovel, municipio, cod_estado, geometry AS geom_wkt
FROM read_csv('lists/goias-sample.csv', header=true, all_varchar=true);
SELECT count(*) FROM list_raw;
SELECT * FROM list_raw WHERE geom_wkt != '' ;
"

cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
-- Brazil bbox from CAR full-file stats
CREATE OR REPLACE TABLE brazil_bbox AS SELECT -73.80074501037598 AS xmin, -34.78797011299997 AS xmax, -33.75084239596 AS ymin, 4.492951075197228 AS ymax;

CREATE OR REPLACE TABLE list_parsed AS
SELECT rn, cod_imovel, municipio, cod_estado, geom_wkt,
  CASE WHEN geom_wkt IS NOT NULL AND geom_wkt != '' THEN ST_GeomFromText(geom_wkt) ELSE NULL END AS geom_orig
FROM list_raw;

SELECT rn, cod_imovel, ST_GeometryType(geom_orig), ST_X(ST_Centroid(geom_orig)), ST_Y(ST_Centroid(geom_orig))
FROM list_parsed WHERE geom_orig IS NOT NULL;
"

cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
SELECT rn, cod_imovel, orig_in_brazil, swapped_in_brazil, was_axis_flipped, geom_use IS NOT NULL AS has_geom_use
FROM list_geom;
"

cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
SELECT cod_imovel, count(*) n FROM car_go WHERE cod_imovel IN (SELECT cod_imovel FROM resolved_ids) GROUP BY 1 HAVING count(*)>1;
"

cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
SELECT count(*) FROM resolved_ids r JOIN car_go c ON r.cod_imovel=c.cod_imovel WHERE c.num_area < 1;
"

cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
CREATE OR REPLACE TABLE listed_parcels AS
SELECT c.* FROM car_go c JOIN resolved_ids r ON c.cod_imovel = r.cod_imovel;
SELECT count(*) FROM listed_parcels;
SELECT min(xmin) xmin, min(ymin) ymin, max(xmax) xmax, max(ymax) ymax FROM listed_parcels;
"

cd /workspace
time timeout 300 duckdb work/db.duckdb -c "
LOAD spatial;
CREATE OR REPLACE TABLE fields_in_envelope AS
SELECT f.* FROM fields_env f, envelope e WHERE ST_Intersects(f.geom, e.geom);
SELECT count(*) FROM fields_in_envelope;
"

cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
SELECT ST_AsText(ST_Transform(ST_Point(-51.4,-15.8), 'EPSG:4326','EPSG:31982'));
"

cd /workspace
time timeout 300 duckdb work/db.duckdb -c "
LOAD spatial;
SET geometry_always_xy = true;
CREATE OR REPLACE TABLE listed_parcels_buffered_union AS
SELECT ST_Transform(
  ST_Union_Agg(
    ST_Buffer(ST_Transform(geom, 'EPSG:4326','EPSG:31982', true), 25)
  ), 'EPSG:31982','EPSG:4326', true
) AS geom
FROM listed_parcels;
SELECT ST_Area(geom) FROM listed_parcels_buffered_union;
"

cd /workspace
time timeout 600 duckdb work/db.duckdb -c "
LOAD spatial;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE field_agg_frac AS
SELECT f.field_id,
  ST_Area(ST_Intersection(f.geom, u.geom)) / ST_Area(f.geom) AS union_frac
FROM fields_in_envelope f, listed_parcels_buffered_union u;

CREATE OR REPLACE TABLE field_single_best AS
WITH ranked AS (
  SELECT field_id, cod_imovel, frac,
    max(frac) OVER (PARTITION BY field_id) AS max_frac
  FROM field_parcel_frac
),
tied AS (
  SELECT field_id, cod_imovel, frac, max_frac
  FROM ranked
  WHERE frac >= max_frac - 1e-9
),
best AS (
  SELECT field_id, cod_imovel, max_frac,
    row_number() OVER (PARTITION BY field_id ORDER BY cod_imovel ASC) AS rn
  FROM tied
)
SELECT field_id, cod_imovel AS primary_cadaster, max_frac AS max_single_frac
FROM best WHERE rn=1;

SELECT count(*) FROM field_single_best;
SELECT count(*) FROM field_agg_frac;
"

cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
SELECT field_id, primary_cadaster, max_single_frac, union_frac FROM field_match
WHERE agg_pass AND NOT single_pass;
"

cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
SET geometry_always_xy=true;
SELECT cod_imovel, num_area,
  ST_Area_Spheroid(geom)/10000.0 AS ha_spheroid_xy,
  ST_Area_Spheroid(ST_FlipCoordinates(geom))/10000.0 AS ha_spheroid_flipped,
  ST_Area(ST_Transform(geom,'EPSG:4326','EPSG:31982',true))/10000.0 AS ha_utm
FROM listed_parcels LIMIT 5;
"

cd /workspace
time duckdb work/db.duckdb -c "
LOAD spatial;
SET geometry_always_xy=true;
SELECT sum(ST_Area_Spheroid(f.geom))/10000.0 AS matched_field_ha
FROM fields_in_envelope f
JOIN field_match fm ON f.field_id = fm.field_id
WHERE fm.single_pass OR fm.agg_pass;
"

cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
SELECT DISTINCT f.mbmode24 FROM fields_in_envelope f JOIN field_match fm ON f.field_id=fm.field_id WHERE fm.single_pass OR fm.agg_pass ORDER BY 1;
"

cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
SET geometry_always_xy=true;
" 
duckdb work/db.duckdb -csv -c "
LOAD spatial;
SET geometry_always_xy=true;
COPY (
  SELECT s.annex1_commodity,
    sum(ST_Area_Spheroid(f.geom))/10000.0 AS total_ha,
    (count(*) FILTER (WHERE f.deforestarea2124>0))::DOUBLE / count(*) AS loss_share
  FROM fields_in_envelope f
  JOIN field_match fm ON f.field_id=fm.field_id
  JOIN scope_table s ON CAST(f.mbmode24 AS INTEGER)=s.mbmode24
  WHERE (fm.single_pass OR fm.agg_pass) AND s.in_scope
  GROUP BY 1 ORDER BY 1
) TO 'answers/q19.csv' WITH (HEADER, DELIMITER ',');
"
cat answers/q19.csv

