cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
SELECT entity_id, weight FROM facilities WHERE tier='membership_muni' AND entity_id IN ('5207600','5212204','5219258');
"

cd /workspace
duckdb work/db.duckdb -c "
LOAD spatial;
SET geometry_always_xy=true;
SELECT fac.entity_id, fac.weight
FROM parcel_centroid_5880 pc, facilities_5880 fac
WHERE pc.cod_imovel='GO-5212204-8F9A53F42FEE4187BBBC3E66F68CEEBE'
